class Subscriptions:Form {Rpc rpc;ListView list=new ListView{Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,HideSelection=false};Label status=new Label{Dock=DockStyle.Bottom,Height=35,Padding=new Padding(10)};Action<Dictionary<string,object>> handler;public Subscriptions(Rpc r){rpc=r;Style.Form(this);Text="Подписки и доступ";Size=new Size(850,460);list.Columns.Add("Клиент",160);list.Columns.Add("Код подписки",130);list.Columns.Add("Сервер",180);list.Columns.Add("Доступ / срок",280);Controls.Add(list);Controls.Add(status);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=54};bar.Controls.Add(Style.Button("Активировать",async(s,e)=>await Activate(this,r,null)));bar.Controls.Add(Style.Button("Обновить",async(s,e)=>await Work("sync",J.D("id",Selected()))));bar.Controls.Add(Style.Button("Обновить все",async(s,e)=>await Work("sync",J.D())));bar.Controls.Add(Style.Button("Удалить",async(s,e)=>{if(Selected()=="")return;if(MessageBox.Show(this,"Удалить подписку и её профили с этого устройства?","TnDtun",MessageBoxButtons.YesNo)==DialogResult.Yes)await Work("remove_subscription",J.D("id",Selected()));}));bar.Controls.Add(Style.Button("Отмена запроса",async(s,e)=>await Work("cancel",J.D())));Controls.Add(bar);handler=m=>{if(!IsDisposed&&IsHandleCreated)BeginInvoke((Action)(()=>Populate(m)));};rpc.State+=handler;FormClosed+=(s,e)=>rpc.State-=handler;Populate(r.Last);}
