з файла",null,async(s,e)=>await Import(null,false,false));menu.Items.Add("QR из изображения",null,async(s,e)=>await Import(null,false,true));import.Click+=(s,e)=>menu.Show(import,0,import.Height);edit.Controls.Add(import);layout.Controls.Add(edit,0,4);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};actions.Controls.Add(Style.Button("Настройки",(s,e)=>new SettingsEditor(rpc,J.Get(current,"settings")).ShowDialog(this)));actions.Controls.Add(Style.Button("Подписки",(s,e)=>new Subscriptions(rpc).ShowDialog(this)));actions.Controls.Add(Style.Button("Экспорт копии",async(s,e)=>{var path=Style.Choose(true,"JSON (*.json)|*.json","TnDtun-backup-"+DateTime.Now.ToString("yyyy-MM-dd")+".json");if(path==null)return;if(MessageBox.Show(this,"Копия содержит приватные ключи. Сохранить её в выбранный файл?","TnDtun",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;try{await rpc.Call("export",J.D("path",path));MessageBox.Show(this,"Копия сохранена.","TnDtun");}catch(Exception ex){Style.Error(this,ex);}}));actions.Controls.Add(Style.Button("Импорт копии",async(s,e)=>{var path=Style.Choose(false,"JSON (*.json)|*.json");if(path==null||MessageBox.Show(this,"Заменить профили и настройки? VPN отключится. Подписки потребуется активировать заново.","TnDtun",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;try{await rpc.Call("import",J.D("path",path,"confirmed",true));}catch(Exception ex){Style.Error(this,ex);}}));layout.Controls.Add(actions,0,5);Controls.Add(layout);tray=new NotifyIcon{Icon=Icon,Text="TnDtun",Visible=true};tray.DoubleClick+=(s,e)=>Restore();var tm=new ContextMenuStrip();tm.Items.Add("Открыть",null,(s,e)=>Restore());tm.Items.Add("Отключить",null,async(s,e)=>{try{await rpc.Call("stop");}catch{}});tm.Items.Add("Выход",null,async(s,e)=>await Exit());tray.ContextMenuStrip=tm;rpc.State+=m=>{if(!IsDisposed&&IsHandleCreated)BeginInvoke((Action)(()=>Apply(m)));};rpc.Fatal+=error=>{if(!IsDisposed&&IsHandleCreated)BeginInvoke((Action)(()=>{current["phase"]="disconnected";current["message"]=error;Apply(current);}));};Shown+=async(s,e)=>{try{Apply(J.Obj(await rpc.Call("state")));}catch(Exception ex){Style.Error(this,ex);}};FormClosing+=(s,e)=>{if(!exiting&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;Hide();}};Apply(r.Last);}
 public void ShowMode(string value){mode=value;modeLoaded=true;Apply(current);}public void Restore(){Show();WindowState=FormWindowState.Normal;Activate();}string Selected(){return profiles.SelectedItems.Count>0?Convert.ToString(profiles.SelectedItems[0].Tag):"";}public void Apply(Dictionary<string,object> m){current=m;if(!modeLoaded&&J.Text(m,"mode")!=""){mode=J.Text(m,"mode");modeLoaded=true;}foreach(var pair in modeButtons){pair.Value.BackColor=pair.Key==mode?Style.Blue:Color.White;pair.Value.ForeColor=pair.Key==mode?Color.White:Style.Ink;}RefreshProfiles(m);string phase=J.Text(m,"phase");var names=new Dictionary<string,string>{{"preparing","Подготовка"},{"connecting","Подключение…"},{"connected","Подключено"},{"recovering","Восстановление TURN…"},{"disconnecting","Отключение…"}};stateLabel.Text=names.ContainsKey(phase)?names[phase]:"Отключено";primary.Text=phase=="disconnected"||phase==""?"Подключить":"Отключить";primary.Enabled=phase!="disconnecting"&&(Selected()!=""||phase!="disconnected"&&phase!="");caption.Text="Профиль: "+J.Rows(J.Get(m,"profiles")).Where(p=>J.Text(p,"id")== (J.Text(m,"active")!=""?J.Text(m,"active"):Selected())).Select(p=>J.Text(p,"title")).FirstOrDefault();metrics.Text="↑ "+Style.Bytes(J.Num(m,"up"))+"    ↓ "+Style.Bytes(J.Num(m,"down"))+"    "+(J.Num(m,"latency")>0?J.Num(m,"latency")+" мс":"— мс");message.Text=profiles.Items.Count==0?"Активируйте доступ в «Подписках» или добавьте свой профиль.":J.Bool(m,"captcha")?"Требуется проверка VK — нажмите «Проверить VK»":J.Text(m,"message");tray.Text="TnDtun · "+stateLabel.Text;}
 void DrawProfileCell(object sender,DrawListViewSubItemEventArgs e){
  bool selected=e.Item.Selected;
  using(var background=new SolidBrush(selected?Style.Blue:profiles.BackColor))e.Graphics.FillRectangle(background,e.Bounds);
  var bounds=e.Bounds;bounds.Inflate(-4,0);
  TextRenderer.DrawText(e.Graphics,e.SubItem.Text,profiles.Font,bounds,selected?Color.White:profiles.ForeColor,TextFormatFlags.SingleLine|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);
 }
 void RefreshProfiles(Dictionary<string,object> state){
  var rows=J.Rows(J.Get(state,"profiles")).Where(p=>J.Text(p,"mode")==mode).ToArray();
  string selected=Selected();if(selected=="")selected=J.Text(state,"selected");
  if(!rows.Any(p=>J.Text(p,"id")==selected))selected=rows.Length>0?J.Text(rows[0],"id"):"";
  updating=true;
  try{
   profiles.BeginUpdate();
   try{
    for(int i=0;i<rows.Length;i++){
     var p=rows[i];var cells=new[]{J.Text(p,"title"),J.Bool(p,"managed")?"Подписка":J.Text(p,"id")=="tndtun.builtin.dns.v1"?"Встроенный":"Ручной",J.Bool(p,"expired")?"Истёк":""};
     if(i>=profiles.Items.Count)profiles.Items.Add(new ListViewItem(cells));
     var item=profiles.Items[i];item.Tag=J.Text(p,"id");
     for(int column=0;column<cells.Length;column++)if(item.SubItems[column].Text!=cells[column])item.SubItems[column].Text=cells[column];
    }
    while(profiles.Items.Count>rows.Length)profiles.Items.RemoveAt(profiles.Items.Count-1);
   }finally{profiles.EndUpdate();}
   foreach(ListViewItem item in profiles.Items){bool chosen=Convert.ToString(item.Tag)==selected;if(item.Selected!=chosen)item.Selected=chosen;}
  }finally{updating=false;}
 }
 async Task EditProfile(){if(Selected()=="")return;try{var p=await rpc.Call("profile",J.D("id",Selected()));if(J.Text(p,"id")=="tndtun.builtin.dns.v1"||J.Text(p,"subscriptionID")!=""){MessageBox.Show(this,"Встроенный профиль и профили подписки изменяются из своего источника.","TnDtun");return;}new ProfileEditor(rpc,p).ShowDialog(this);}catch(Exception e){Style.Error(this,e);}}
 async Task Import(string value,bool clipboard,bool qr){try{if(clipboard)value=Clipboard.GetText();if(value==null){var path=Style.Choose(false,qr?"Изображения|*.png;*.jpg;*.jpeg;*.gif":"Профили|*.json;*.conf;*.txt|Все файлы|*.*");if(path==null)return;if(qr)value=Convert.ToString(await rpc.Call("qr",J.D("path",path)));else{var p=await rpc.Call("import_profile",J.D("path",path));new ProfileEditor(rpc,p).ShowDialog(this);return;}}if(value.Trim().StartsWith("tndtun:",StringComparison.OrdinalIgnoreCase)){await Subscriptions.Activate(this,rpc,value);return;}var profile=await rpc.Call("import_profile",J.D("text",value));new ProfileEditor(rpc,profile).ShowDialog(this);}catch(Exception e){Style.Error(this,e);}}
 public async Task Exit(){if(exiting)return;exiting=true;Enabled=false;try{await rpc.Call("stop");}catch{}await Task.Run(()=>rpc.Dispose());tray.Dispose();Close();Application.Exit();}
}
static class Instance {
 static string Name {get{return "TnDtun-"+WindowsIdentity.GetCurrent().User.Value+"-"+Process.GetCurrentProcess().SessionId;}}
 public static void Forward(string[] args){try{using(var pipe=new NamedPipeClientStream(".",Name,PipeDirection.Out)){pipe.Connect(3000);using(var w=new StreamWriter(pipe,new UTF8Encoding(false))){w.WriteLine(J.Encode(J.D("activation",args.Length==2&&args[0]=="--activate"?args[1]:"")));}}}catch{MessageBox.Show("Не удалось открыть запущенное окно. Откройте TnDtun из области уведомлений.","TnDtun");}}
 public static void Listen(MainForm f,Rpc rpc){var thread=new Thread(()=>{while(!f.IsDisposed){try{var security=new PipeSecurity();security.SetAccessRuleProtection(true,false);security.AddAccessRule(new PipeAccessRule(WindowsIdentity.GetCurrent().User,PipeAccessRights.FullControl,System.Security.AccessControl.AccessControlType.Allow));using(var pipe=new NamedPipeServerStream(Name,PipeDirection.In,1,PipeTransmissionMode.Byte,PipeOptions.None,8192,8192,security)){pipe.WaitForConnection();using(var reader=new StreamReader(pipe,Encoding.UTF8)){var chars=new List<char>();while(chars.Count<=16384){int c=reader.Read();if(c<0||c=='\n')break;chars.Add((char)c);}if(chars.Count>16384)continue;var value=J.New().DeserializeObject(new string(chars.ToArray()));string activation=J.Text(value,"activation");if(!f.IsDisposed&&f.IsHandleCreated)f.BeginInvoke((Action)(async()=>{f.Restore();if(activation!="")await Subscriptions.Activate(f,rpc,activation);}));}}}catch{if(f.IsDisposed)return;Thread.Sleep(250);}}});thread.IsBackground=true;thread.Start();}
}
static class Program {static void Capture(Form f,string path){f.Refresh();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(path);}} [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var rpc=new Rpc()){if(args.Length==2&&args[0]=="--smoke"){rpc.TestHome=Path.Combine(args[1],"isolated-state");using(var f=new MainForm(rpc)){var timer=new System.Windows.Forms.Timer{Interval=2500};timer.Tick+=(s,e)=>{timer.Stop();try{Directory.CreateDirectory(args[1]);using(var bmp=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(Path.Combine(args[1],"TnDtun-main.png"));}foreach(var value in new[]{"turn","dns"}){f.ShowMode(value);Capture(f,Path.Combine(args[1],"TnDtun-"+value+".png"));}using(var editor=new SettingsEditor(rpc,J.Get(rpc.Last,"settings"))){editor.Show();Capture(editor,Path.Combine(args[1],"TnDtun-settings.png"));editor.Close();}using(var editor=new ProfileEditor(rpc,J.D("mode","dns"))){editor.Show();Capture(editor,Path.Combine(args[1],"TnDtun-profile.png"));editor.Close();}File.WriteAllText(Path.Combine(args[1],"ui-smoke.json"),J.Encode(rpc.Last),Encoding.UTF8);}finally{rpc.Dispose();Environment.Exit(0);}};timer.Start();Application.Run(f);}return;}bool first;using(var mutex=new Mutex(true,"Local\\TnDtun-"+WindowsIdentity.GetCurrent().User.Value,out first)){if(!first){Instance.Forward(args);return;}using(var f=new MainForm(rpc)){Instance.Listen(f,rpc);if(args.Length==2&&args[0]=="--activate")f.Shown+=async(s,e)=>await Subscriptions.Activate(f,rpc,args[1]);Application.Run(f);}}}}
}
